    event QuoteAssetRemoved(IERC20 indexed quoteAsset);

    event DLMMVoterSet(address indexed oldVoter, address indexed newVoter);

    function getMinBinStep() external pure returns (uint256);

    function getFeeRecipient() external view returns (address);

    function feeCollector() external view returns (address);

    function voter() external view returns (address);

    function setVoter(address voter) external;

    function defaultProtocolShare() external pure returns (uint16);

    function gaugedProtocolShare() external pure returns (uint16);

    function isPool(address pool) external view returns (bool);

    function setPoolProtocolShare(address pool, uint16 protocolShare) external;

    function setPoolDefaultProtocolShare(address pool) external;

    function setPoolGaugedProtocolShare(address pool) external;

